import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { playbackHealth } from "../src/health/app.ts";

type DbState = "up" | "down" | "hanging";

function setup(opts: { db?: DbState; originStatus?: number; titles?: number } = {}) {
    const state = { db: opts.db ?? "up", originStatus: opts.originStatus ?? 200, dbQueries: 0 };
    const app = playbackHealth({
        timeoutMs: 30,
        db: {
            async query() {
                state.dbQueries++;
                await tick();
                if (state.db === "down") throw new Error("connection refused");
                if (state.db === "hanging") await new Promise(() => {});
                return [{ "?column?": 1 }];
            },
        },
        origin: { head: async () => ({ status: state.originStatus }) },
        catalog: { load: async () => opts.titles ?? 1200 },
    });
    return { app, state };
}

test("readiness is 503 until the catalog is loaded, then 200", async () => {
    const { app } = setup();
    assert.deepEqual([(await app.readyz()).status, (await app.readyz()).body.reason], [503, "starting"]);
    await app.boot();
    const ready = await app.readyz();
    assert.equal(ready.status, 200);
    assert.equal(ready.body.status, "ok");
});

test("readiness is 503 while the database is unreachable", async () => {
    const { app } = setup({ db: "down" });
    await app.boot();
    const ready = await app.readyz();
    assert.equal(ready.status, 503);
    assert.deepEqual(ready.body.checks.find((c) => c.name === "postgres"), { name: "postgres", critical: true, ok: false, error: "connection refused" });
});

test("a broken thumbnail origin degrades readiness but keeps serving traffic", async () => {
    const { app } = setup({ originStatus: 502 });
    await app.boot();
    const ready = await app.readyz();
    assert.equal(ready.status, 200);
    assert.equal(ready.body.status, "degraded");
});

test("liveness stays 200 during a database outage, so pods aren't restarted for it", async () => {
    const { app, state } = setup();
    await app.boot();
    state.db = "down";
    const live = await app.livez();
    console.log("GET /livez during a database outage:", live);
    assert.equal(live.status, 200);
    assert.equal((await app.readyz()).status, 503);
});

test("a liveness probe doesn't touch the database", async () => {
    const { app, state } = setup({ db: "hanging" });
    await app.boot();
    const before = state.dbQueries;
    for (let i = 0; i < 5; i++) assert.equal((await app.livez()).status, 200);
    assert.equal(state.dbQueries, before);
});

test("a dependency that hangs is reported as timed out instead of stalling readiness", async () => {
    const { app } = setup({ db: "hanging" });
    await app.boot();
    const ready = await app.readyz();
    assert.equal(ready.status, 503);
    assert.equal(ready.body.checks.find((c) => c.name === "postgres")?.error, "timed out after 30ms");
});

test("draining stops traffic but keeps the pod alive; corrupted license keys restart it", async () => {
    const { app } = setup();
    await app.boot();
    app.onSigterm();
    assert.deepEqual([(await app.readyz()).status, (await app.livez()).status], [503, 200]);
    app.onLicenseKeysCorrupted();
    const live = await app.livez();
    assert.deepEqual([live.status, live.body.reason], [503, "license keys corrupted"]);
});
